								},
							},
						},
					},
				},
			},
			expectedErrors: 1,
			expectedKinds:  []string{"Security/Pod"},
		},
		{
			name:      "wildcard permissions in role",
			namespace: "default",
			roles: []rbacv1.Role{
				{
					ObjectMeta: metav1.ObjectMeta{
						Name:      "wildcard-role",
						Namespace: "default",
